INSERT INTO post (id, board_id, author_id, title, content, status, visibility, view_count, like_count, comment_count, published_at, created_at, updated_at, deleted_at) VALUES
(1, 3, 4, 'MySQL 인덱스 설계 질문드립니다', '운영 환경에서는 조금 다르게 동작할 수 있으니 주의하세요. 처음에는 원인을 몰라서 한참 헤맸습니다. 같은 문제를 겪는 분께 도움이 되면 좋겠습니다. 로그를 찍어 보니 쿼리가 생각보다 많이 나가고 있었습니다.', 'PUBLISHED', 'PUBLIC', 38, 2, 0, '2026-07-01 05:09:10', '2026-07-01 03:47:10', '2026-07-01 05:09:10', NULL),
(2, 1, 1, '[공지] 커뮤니티 이용 규칙 안내', '안녕하세요, 운영자입니다. 결론부터 말하면 설계를 바꾸는 게 맞았습니다. 운영 환경에서는 조금 다르게 동작할 수 있으니 주의하세요.', 'PUBLISHED', 'PUBLIC', 52, 6, 1, '2026-07-01 11:00:00', '2026-07-01 10:00:00', '2026-07-01 11:00:00', NULL),
(3, 4, 18, '첫 코드리뷰 받은 날', '로그를 찍어 보니 쿼리가 생각보다 많이 나가고 있었습니다. 테스트를 먼저 작성하고 나니 리팩토링이 쉬워졌어요. 같은 문제를 겪는 분께 도움이 되면 좋겠습니다. 댓글로 더 좋은 방법을 알려주시면 감사하겠습니다. 처음에는 원인을 몰라서 한참 헤맸습니다.', 'PUBLISHED', 'FOLLOWERS', 63, 1, 3, '2026-07-01 14:43:07', '2026-07-01 13:22:07', '2026-07-01 14:43:07', NULL),
(4, 3, 22, '페이징 구현 이렇게 하는 게 맞나요?', '처음에는 원인을 몰라서 한참 헤맸습니다. 테스트를 먼저 작성하고 나니 리팩토링이 쉬워졌어요. 댓글로 더 좋은 방법을 알려주시면 감사하겠습니다.', 'PUBLISHED', 'PUBLIC', 35, 1, 3, '2026-07-02 22:50:57', '2026-07-02 21:24:57', '2026-07-02 22:50:57', NULL),
(5, 2, 28, 'JPA N+1 문제 비교해보기', '예제 코드는 최대한 단순하게 줄였습니다. 테스트를 먼저 작성하고 나니 리팩토링이 쉬워졌어요. 팀원들과 리뷰하면서 정리한 내용입니다.', 'PUBLISHED', 'PUBLIC', 36, 1, 4, '2026-07-03 06:06:20', '2026-07-03 05:13:20', '2026-07-03 06:06:20', NULL),
(6, 3, 5, '예외 처리 전략 에러가 나요', '공식 문서를 다시 읽어 보니 설정 하나가 빠져 있었어요. 처음에는 원인을 몰라서 한참 헤맸습니다. 댓글로 더 좋은 방법을 알려주시면 감사하겠습니다.', 'PUBLISHED', 'PUBLIC', 71, 3, 1, '2026-07-03 07:38:01', '2026-07-03 06:38:01', '2026-07-03 07:38:01', NULL),
(7, 3, 5, 'Docker Compose 로컬 환경 에러가 나요', '로그를 찍어 보니 쿼리가 생각보다 많이 나가고 있었습니다. 팀원들과 리뷰하면서 정리한 내용입니다. 처음에는 원인을 몰라서 한참 헤맸습니다. 예제 코드는 최대한 단순하게 줄였습니다. 테스트를 먼저 작성하고 나니 리팩토링이 쉬워졌어요.', 'DRAFT', 'PUBLIC', 0, 0, 0, NULL, '2026-07-03 07:48:46', '2026-07-03 07:48:46', NULL),
